def compare_versions(a: str, b: str) -> int:
    def parse_version(v: str):
        # Split off build metadata (ignored)
        v = v.split('+')[0]

        # Split core version and pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = v
            prerelease_parts = None

        # Parse core version
        major, minor, patch = map(int, core.split('.'))

        return (major, minor, patch, prerelease_parts)

    def parse_prerelease_identifier(identifier: str):
        # Returns (is_numeric, value)
        # Numeric identifiers compare as integers
        # Non-numeric identifiers compare as strings
        # Numeric identifiers have lower precedence than non-numeric
        if identifier.isdigit():
            return (True, int(identifier))
        else:
            return (False, identifier)

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare core version (major, minor, patch)
    if major_a != major_b:
        return -1 if major_a < major_b else 1
    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1
    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    # Core versions are equal, compare pre-release
    # A version without pre-release has higher precedence than one with
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    # Both have pre-release, compare identifiers
    for i in range(max(len(pre_a), len(pre_b))):
        # If one has fewer identifiers, it has lower precedence
        if i >= len(pre_a):
            return -1
        if i >= len(pre_b):
            return 1

        is_num_a, val_a = parse_prerelease_identifier(pre_a[i])
        is_num_b, val_b = parse_prerelease_identifier(pre_b[i])

        # Numeric identifiers have lower precedence than non-numeric
        if is_num_a and not is_num_b:
            return -1
        if not is_num_a and is_num_b:
            return 1

        # Both same type, compare values
        if val_a < val_b:
            return -1
        if val_a > val_b:
            return 1

    return 0
